//! Arabic Benchmark v1: 100+ questions (MSA, Egyptian dialect, Arabic/English
//! mixing, technical terms, spelling mistakes, format following) with
//! accepted answers, scored after Arabic normalization. Dataset:
//! `core/benchmarks/arabic_v1.json` (generated by scripts/gen_arabic_bench.py).
//! Greedy decoding, fixed prompt ⇒ reproducible on the same model/device.

use ara_core_api::{AraResult, CancellationToken};
use ara_inference::{ChatMessage, GenerationParams, LoadedModel, Role};
use ara_search::normalize::normalize;
use serde::{Deserialize, Serialize};
use std::collections::BTreeMap;

const DATA: &str = include_str!("../../../benchmarks/arabic_v1.json");
const SYSTEM: &str = "أجب باللغة العربية بإيجاز.";

#[derive(Debug, Clone, Deserialize)]
pub struct Item {
    pub id: String,
    pub cat: String,
    pub q: String,
    pub accept: Vec<String>,
    pub lang: String,
    pub max_words: Option<usize>,
}

#[derive(Deserialize)]
struct File {
    items: Vec<Item>,
}

pub fn items() -> Vec<Item> {
    serde_json::from_str::<File>(DATA)
        .expect("embedded dataset is valid")
        .items
}

fn arabic_ratio(s: &str) -> f32 {
    let letters = s.chars().filter(|c| c.is_alphabetic()).count();
    if letters == 0 {
        return 0.0;
    }
    s.chars()
        .filter(|c| ('\u{0600}'..='\u{06FF}').contains(c))
        .count() as f32
        / letters as f32
}

/// Why an answer failed, or None if it passed.
pub fn judge(item: &Item, reply: &str) -> Option<&'static str> {
    let r = normalize(reply);
    if !item.accept.iter().any(|a| r.contains(&normalize(a))) {
        return Some("wrong_answer");
    }
    if item.lang == "ar" && arabic_ratio(reply) < 0.5 && !reply.chars().any(|c| c.is_ascii_digit())
    {
        return Some("not_arabic");
    }
    if item
        .max_words
        .is_some_and(|m| reply.split_whitespace().count() > m)
    {
        return Some("too_long");
    }
    None
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, Default)]
pub struct ArabicReport {
    pub model_id: String,
    pub total: u32,
    pub passed: u32,
    pub by_category: BTreeMap<String, (u32, u32)>,
    pub failures: Vec<String>,
}

impl ArabicReport {
    pub fn score(&self) -> f32 {
        if self.total == 0 {
            0.0
        } else {
            self.passed as f32 / self.total as f32
        }
    }
}

pub fn run(
    model: &mut dyn LoadedModel,
    model_id: &str,
    limit: Option<usize>,
) -> AraResult<ArabicReport> {
    let mut rep = ArabicReport {
        model_id: model_id.into(),
        ..Default::default()
    };
    for item in items().into_iter().take(limit.unwrap_or(usize::MAX)) {
        let mut out = String::new();
        model.generate_chat(
            &[
                ChatMessage::new(Role::System, SYSTEM),
                ChatMessage::new(Role::User, item.q.clone()),
            ],
            &GenerationParams {
                max_tokens: 60,
                temperature: 0.0,
                ..Default::default()
            },
            &CancellationToken::new(),
            &mut |t| out.push_str(t),
        )?;
        let e = rep.by_category.entry(item.cat.clone()).or_default();
        e.1 += 1;
        rep.total += 1;
        match judge(&item, &out) {
            None => {
                e.0 += 1;
                rep.passed += 1;
            }
            Some(why) => rep.failures.push(format!(
                "{} [{}] {}: {} -> {}",
                item.id,
                item.cat,
                why,
                item.q,
                out.trim().chars().take(160).collect::<String>()
            )),
        }
    }
    Ok(rep)
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::collections::HashSet;

    #[test]
    fn dataset_is_valid_and_balanced() {
        let it = items();
        assert!(it.len() >= 100, "{}", it.len());
        let ids: HashSet<_> = it.iter().map(|i| i.id.clone()).collect();
        assert_eq!(ids.len(), it.len(), "unique ids");
        let mut cats: BTreeMap<&str, usize> = BTreeMap::new();
        for i in &it {
            *cats.entry(i.cat.as_str()).or_default() += 1;
            assert!(
                !i.accept.is_empty() && i.accept.iter().all(|a| !a.trim().is_empty()),
                "{}",
                i.id
            );
            assert!(["ar", "any"].contains(&i.lang.as_str()));
        }
        assert_eq!(cats.len(), 6);
        assert!(cats.values().all(|n| *n >= 14), "{cats:?}");
    }

    #[test]
    fn judge_normalizes_and_checks_language_and_length() {
        let it = items();
        let find = |id: &str| it.iter().find(|i| i.id == id).unwrap().clone();
        let cap = it
            .iter()
            .find(|i| i.q.contains("اليابان") && i.cat == "msa")
            .unwrap();
        assert_eq!(judge(cap, "عاصمة اليابان هي طُوكيو."), None);
        assert_eq!(judge(cap, "Tokyo"), Some("wrong_answer"));
        let eg = it.iter().find(|i| i.q.contains("عاصمة مصر إيه")).unwrap();
        assert_eq!(judge(eg, "القاهره"), None, "ة/ه variation accepted");
        assert_eq!(judge(eg, "The answer is القاهرة and more words follow here to dilute the arabic ratio considerably"), Some("not_arabic"));
        let fmt = it.iter().find(|i| i.q.contains("لون الموز")).unwrap();
        assert_eq!(judge(fmt, "أصفر"), None);
        assert_eq!(
            judge(fmt, "لون الموز عادة هو أصفر كما هو معروف للجميع"),
            Some("too_long")
        );
        let _ = find("ar001");
    }

    #[test]
    fn oracle_scores_100_and_silent_model_0() {
        struct Oracle(bool);
        impl LoadedModel for Oracle {
            fn context_len(&self) -> u32 {
                4096
            }
            fn trained_context_len(&self) -> u32 {
                4096
            }
            fn count_tokens(&self, t: &str) -> AraResult<u32> {
                Ok(t.len() as u32)
            }
            fn generate_chat(
                &mut self,
                m: &[ChatMessage],
                _: &GenerationParams,
                _: &CancellationToken,
                on: &mut dyn FnMut(&str),
            ) -> AraResult<ara_inference::GenerationStats> {
                let q = &m.last().unwrap().content;
                if self.0 {
                    let it = items().into_iter().find(|i| &i.q == q).unwrap();
                    // Answer with the first accepted answer, in Arabic framing if needed.
                    let a = &it.accept[0];
                    on(&if it.lang == "ar"
                        && !a.chars().any(|c| c > '\u{0600}')
                        && !a.chars().all(|c| c.is_ascii_digit())
                    {
                        format!("الإجابة {a}")
                    } else {
                        a.clone()
                    });
                }
                Ok(ara_inference::GenerationStats {
                    prompt_tokens: 1,
                    generated_tokens: 1,
                    prompt_eval_ms: 0,
                    time_to_first_token_ms: 0,
                    generation_ms: 0,
                    tokens_per_sec: 0.0,
                    stop_reason: ara_inference::StopReason::EndOfGeneration,
                    reused_prompt_tokens: 0,
                })
            }
        }
        let r = run(&mut Oracle(true), "oracle", None).unwrap();
        assert!(r.failures.is_empty(), "{:#?}", r.failures);
        assert_eq!(r.passed, r.total);
        let r0 = run(&mut Oracle(false), "silent", None).unwrap();
        assert_eq!(r0.passed, 0);
        assert!((r0.score() - 0.0).abs() < 1e-6);
    }
}
